private static Schema<?> keySchema(String text) {
    String t = "string"; String desc = text==null?"":text;
    if (text != null) {
        String lower = text.toLowerCase(Locale.ROOT);
        for (String cand : List.of("integer","number","boolean","object","array","string")) {
            if (lower.startsWith(cand)) { t=cand; desc=text.substring(cand.length()).replaceFirst("^[\\s:：,，-]+",""); break; }
        }
    }
    Schema<?> s = switch (t) {
        case "integer" -> new IntegerSchema();
        case "number" -> new NumberSchema();
        case "boolean" -> new BooleanSchema();
        case "object" -> new ObjectSchema();
        case "array" -> new ArraySchema().items(new Schema<>().type("string"));
        default -> new StringSchema();
    };
    if (!desc.isBlank()) s.setDescription(desc);
    return s;
}
```

