        Map<String, ApiDocEntry> entries = new LinkedHashMap<>(validCatalog().entries());
        // GET 真实参数为 itemId + limit；这里刻意漏掉 limit、多加 ghost
        entries.put("GET /api/v1/synthetic/items/{itemId}", new ApiDocEntry(
