                        ParamDoc("itemId", "path", "项 ID", null, null),
                        ParamDoc("ghost", "query", "多余参数", null, null)),
                List.of(), null, null,
                List.of(ApiDocEntry.SuccessDoc.json("200", "ok", SyntheticResult.class)),
