package cn.yuanxin.mvp.web.docs.sample;

import cn.yuanxin.mvp.web.auth.GimbalSessionController;
import cn.yuanxin.mvp.web.docs.catalog.ApiDocEntry;
import cn.yuanxin.mvp.web.docs.catalog.ApiDocsCatalog;
import cn.yuanxin.mvp.web.error.ErrorCode;
import cn.yuanxin.mvp.web.identity.MemberAccessGrantController;
import io.swagger.v3.oas.models.tags.Tag;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Component;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * <p><b>临时联调样例目录（仅用于本任务的真实 /v3/api-docs 证据，交付前删除）</b>：
 * 只覆盖 3 个真实操作，证明引擎在真实生成文档上生效。通过
 * {@code --app.docs.sample=true} 显式启用（默认不装配，绝不与后续四条目录道冲突；
 * 未启用时本类不产生任何 bean）。</p>
 *
 * <p>它<strong>不是</strong>权威文档内容，仅演示施加效果；正式内容由四条按域目录道提供。</p>
 */
@Component
@Profile({"dev", "test"})
@ConditionalOnProperty(name = "app.docs.sample", havingValue = "true")
public class SampleDocsCatalog implements ApiDocsCatalog {

    @Override
    public String domain() {
        return "sample";
    }

    @Override
    public List<Tag> tags() {
        return List.of(new Tag().name("联调样例").description("仅用于联调文档施加效果演示（临时）"));
    }

